(function(){
 var raw=String(result||'');
 var out=[];
 try{
  var doc=Packages.org.jsoup.Jsoup.parse(raw);
  var cand=null;
  // A) 裸IP「笔趣阁」模板：多个 ul.list-charts，选章节链接最多的段（全部章节段）
  var uls=doc.select('ul.list-charts');
  var best=0;
  for(var i=0;i<uls.size();i++){
   var n=uls.get(i).select('a[href*=.html]').size();
   if(n>best){best=n;cand=uls.get(i);}
  }
  // B) 域名「久久小说网」模板：单个 dl，dt[0]=最新章节(倒序9) / dt[1]=全部章节目录(正序)
  //    必须从「全部章节目录」dt 之后开始取，避免最新章节排到最前；末尾还会重复最新9条 → 按 href 去重
  if(!cand || best<20){
   var dls=doc.select('dl');
   for(var d=0;d<dls.size();d++){
    var dl=dls.get(d);
    var dts=dl.select('dt');
    var anchor=null;
    for(var t=0;t<dts.size();t++){
     if(dts.get(t).text().indexOf('全部章节目录')>=0){anchor=dts.get(t);break;}
    }
    if(anchor){
     var kids=dl.children();
     var start=kids.indexOf(anchor);
     // 收集 anchor 之后所有带数字章节 href 的 a（含 dt[2] 之后的 hc 段，仍正序）
     var tmp=[];
     for(var q=start+1;q<kids.size();q++){
      var e=kids.get(q);
      var as=e.tagName()==='a'?[e]:e.select('a');
      for(var z=0;z<as.length;z++){
       var a=as[z],h=a.attr('href')||'',tx=a.text()||'';
       if(/\/\d+_\d+\/\d+\.html/.test(h))tmp.push(JSON.stringify({n:tx,u:h}));
      }
     }
     if(tmp.length>best){best=tmp.length;cand={_items:tmp};}
    }
   }
  }
  if(cand){
   var items=[];
   if(cand._items){ items=cand._items; }
   else{
    var as2=cand.select('a');
    for(var j=0;j<as2.size();j++){
     var a2=as2.get(j),h2=a2.attr('href')||'',t2=a2.text()||'';
     if(!/\/\d+_\d+\/\d+\.html/.test(h2))continue;
     items.push(JSON.stringify({n:t2,u:h2}));
    }
   }
   // 按 href 去重（保先出现）：域名侧末尾会重复最新9条，裸IP侧各段互不重叠
   var seen={};
   for(var k=0;k<items.length;k++){
    var o=JSON.parse(items[k]);
    if(seen[o.u])continue;seen[o.u]=1;
    out.push(items[k]);
   }
  }
 }catch(e){}
 var list=new Packages.java.util.ArrayList();
 for(var m=0;m<out.length;m++)list.add(out[m]);
 return list;
})()

