source.loginCheckJs:
(function(){
 var R=result;
 try{
  var b=String(R.body()||'');
  var waf=b.indexOf('宝塔防火墙')>=0||b.indexOf('Verification_auth_btwaf')>=0||b.indexOf('请输入验证码')>=0;
  if(!waf){
   if(b.indexOf('搜索间隔: 30 秒')>=0) java.toast('久久小说：站点搜索间隔 30 秒，已自动清会话重试；若仍出现请稍后再搜');
   return R;
  }
  var u=String(R.url());
  var root=u.replace(/^(https?:\/\/[^\/]+).*$/,'$1');
  java.toast('久久小说：① 触发宝塔人机验证，正在获取验证码图片…');
  var capUrl=root+'/get_btwaf_captcha_base64?captcha='+Date.now();
  var capRaw=String(java.ajax(capUrl));
  var cap='';
  try{ var cj=JSON.parse(capRaw); if(cj&&cj.msg) cap=String(cj.msg); }catch(e){}
  if(!cap||cap.indexOf('iVBOR')<0){ java.toast('久久小说：✗ 验证码图片获取失败，请稍后重试或切换线路'); return R; }
  var code='';
  try{ code=String(java.getVerificationCode('data:image/png;base64,'+cap)||'').replace(/^\s+|\s+$/g,''); }
  catch(e){ java.toast('久久小说：✗ 验证码弹窗失败：'+e); return R; }
  if(!code){ java.toast('久久小说：✗ 已取消验证码输入，本次搜索终止'); return R; }
  java.toast('久久小说：② 已收到验证码，正在提交校验…');
  var vUrl=root+'/Verification_auth_btwaf?captcha='+encodeURIComponent(code);
  var vRaw=String(java.ajax(vUrl));
  var ok=false;
  try{ var vj=JSON.parse(vRaw); ok=!!(vj&&vj.status); }catch(e){ ok=vRaw.indexOf('true')>=0; }
  if(!ok){ java.toast('久久小说：✗ 验证码错误或已过期，请重新搜索再试'); return R; }
  java.toast('久久小说：③ 验证通过，正在继续本次搜索…');

  // ★按 Host 分派重放接口：域名过盾后是「久久小说网」模板(GET /search/?searchkey=)，
  //   裸IP是「笔趣阁」模板(POST /search7e.html)。验证成功后的放行窗口很短，必须立刻重放。
  var isDomain=root.indexOf('ijjxs.org')>=0;
  var kw='';
  try{ kw=String(key||''); }catch(e){}
  if(!kw){
   try{
    var rb0=R.raw().request().body();
    if(rb0){ var B0=new Packages.okio.Buffer(); rb0.writeTo(B0);
     var m=String(B0.readUtf8()).match(/searchkey=([^&]*)/); if(m) kw=decodeURIComponent(m[1]); }
   }catch(e){}
  }
  var replayUrl='', replay='';
  if(isDomain){
   // 域名侧：搜索/发现/详情/正文全部用 GET 路径；这里只重放「本次被拦的请求」对应的域名侧等价 URL
   var path=u.slice(root.length);
   if(path.indexOf('/search')===0){
    replayUrl=root+'/search/?searchkey='+encodeURIComponent(kw);
   }else if(path.indexOf('/class')===0||path.indexOf('/rank')===0||path.indexOf('/quanben')===0){
    replayUrl=root+path;   // 分类/排行/全本路径两侧同名
   }else{
    replayUrl=root+path;   // 详情/章节路径两侧同名
   }
   try{ replay=String(java.ajax(replayUrl)); }
   catch(e){ java.toast('久久小说：✗ 过盾后重放失败：'+e); return R; }
  }else{
   // 裸IP侧：原样重放（method+body），但不回填全部原请求头，避免重复 Connection/Keep-Alive/Cookie
   var req=R.raw().request();
   var method=String(req.method()||'GET');
   replayUrl=String(req.url());
   var body='';
   try{
    var rb=req.body();
    if(rb){ var B=new Packages.okio.Buffer(); rb.writeTo(B); body=String(B.readUtf8()); }
   }catch(e){}
   var opt={method:method};
   if(body) opt.body=body;
   try{ replay=String(java.ajax(replayUrl+','+JSON.stringify(opt))); }
   catch(e){ java.toast('久久小说：✗ 过盾后重放失败：'+e); return R; }
  }
  if(replay.indexOf('宝塔防火墙')>=0||replay.indexOf('请输入验证码')>=0){
   java.toast('久久小说：⚠ 验证已提交但页面仍被拦截，请在浏览器过盾后再搜，或切到裸IP线路');
   return R;
  }
  if(replay.indexOf('404 Not Found')>=0){
   java.toast('久久小说：⚠ 过盾成功但重放地址不存在（'+replayUrl+'），请切到裸IP线路');
   return R;
  }
  try{
   var NR=new Packages.io.legado.app.help.http.StrResponse(replayUrl,replay);
   return NR;
  }catch(e){
   java.toast('久久小说：✗ 响应重建失败：'+e);
   return R;
  }
 }catch(e){
  try{ java.toast('久久小说：✗ 人机验证处理异常：'+e); }catch(e2){}
  return R;
 }
})()

source.loginUrl:
function login(){return 'ok';}
function IJ_toast(jv,s){try{jv.toast(s)}catch(e){}try{jv.longToast(s)}catch(e){}}
function IJ_gv(jv,k,d){
 var v='';try{v=String(jv.get(k)||'')}catch(e){}
 if(!v||v==='null'||v==='undefined')v=d||'';return v;
}
function IJ_line(jv){
 var v=IJ_gv(jv,'ijLine','');
 if(!v||v.indexOf('http')!==0)v='http://177.5.49.192';
 return v.replace(/\/+$/,'');
}
function IJ_btn(jv,n){
 var list=IJ_gv(jv,'ijLines','').split('|'),i=Number(n)-1;
 if(i<0||i>=list.length||!list[i])return '━━ 线路'+n+' 未获取 ━━';
 var cur=IJ_line(jv),mark=(list[i]===cur)?'▶ ':'　 ';
 var d=IJ_gv(jv,'ijDelay'+n,'');if(d)mark+=d+' ';
 return mark+list[i].replace(/^https?:\/\//,'').replace(/\/+$/,'');
}
function IJ_reUi(jv){try{jv.reLoginView(false)}catch(e){try{jv.reUiView(false)}catch(e2){}}}
function IJ_apply(jv){
 var v=IJ_gv(jv,'ijPub','').replace(/^\s+|\s+$/g,'');
 if(!v)return '';
 if(v.indexOf('http')!==0)v='http://'+v;
 v=v.replace(/\/+$/,'');
 var pool=IJ_gv(jv,'ijLines','');
 if(pool.split('|').indexOf(v)<0)pool=(pool?pool+'|':'')+v;
 jv.put('ijLines',pool);jv.put('ijLine',v);
 return v;
}
function IJ_fetch(jv){
 IJ_toast(jv,'① 正在从发布页/输入框获取网址路线…');
 var pub=IJ_gv(jv,'ijPub','').replace(/^\s+|\s+$/g,'');
 var found=[];
 if(pub){
  if(pub.indexOf('http')!==0)pub='http://'+pub;
  try{
   var h=String(jv.ajax(pub));
   IJ_toast(jv,'② 已打开发布页，正在解析页面中的网址…');
   var re=/https?:\/\/[a-z0-9.\-]+(?:\/[^\s"'<>]*)?/gi,m;
   while((m=re.exec(h))!==null){
    var u=m[0].replace(/\/+$/,'');
    var host=u.replace(/^https?:\/\//,'').split('/')[0];
    if(/^(www\.)?(w3\.org|cloudflare|cloudfront|google|baidu|alicdn|qq|weibo|cnzz|51\.la|doubleclick|gstatic|bootstrapcdn|jquery|jsdelivr|unpkg)\b/i.test(host))continue;
    if(found.indexOf(u)<0)found.push(u);
   }
  }catch(e){IJ_toast(jv,'发布页读取失败：'+e);}
 }else{
  IJ_toast(jv,'② 未填发布页，改用内置线路池：域名 + 裸IP直连');
 }
 var defs=['http://www.ijjxs.org','http://177.5.49.192'];
 for(var i=0;i<defs.length;i++)if(found.indexOf(defs[i])<0)found.push(defs[i]);
 jv.put('ijLines',found.join('|'));
 IJ_toast(jv,'③ 获取完成，共 '+found.length+' 条路线；点「⏱ 测试延时」测速');
 IJ_reUi(jv);
 return found.join('|');
}
function IJ_body(x){
 try{ if(x&&x.body) return String(x.body()); }catch(e){}
 return String(x||'');
}
function IJ_speed(jv){
 IJ_toast(jv,'① 开始测速（并发，跳过全局限速）…');
 var list=IJ_gv(jv,'ijLines','').split('|'),clean=[];
 for(var z=0;z<list.length;z++)if(list[z])clean.push(list[z].replace(/\/+$/,''));
 if(!clean.length){IJ_toast(jv,'✗ 线路池为空，请先点「🧭 一键获取网址路线」');return '';}
 var urls=[];
 for(var i=0;i<clean.length;i++)urls.push(clean[i]+'/');
 var res=[],t0=Date.now(),done=false;
 try{
  var rs=jv.ajaxAll(urls,true);
  for(var k=0;k<clean.length;k++){
   var rr=null;try{rr=rs.get(k)}catch(e){}
   var s=IJ_body(rr);
   var ok=s.length>5000&&s.indexOf('Exception')<0&&s.indexOf('宝塔防火墙')<0;
   var ct='';
   try{if(rr&&rr.callTime)ct=String(rr.callTime())+'ms';}catch(e){}
   if(!ok)ct='超时/验证';
   if(!ct)ct=ok?'可达':'超时/验证';
   jv.put('ijDelay'+(k+1),ct);
   res.push(clean[k]+'='+ct);
  }
  done=true;
 }catch(e){IJ_toast(jv,'并发测速不可用，改串行：'+e);}
 if(!done){
  for(var q=0;q<clean.length;q++){
   var st=Date.now(),ok2=false;
   try{
    var s2=String(jv.ajax(clean[q]+'/,'+JSON.stringify({timeout:8000})));
    ok2=s2.length>5000&&s2.indexOf('宝塔防火墙')<0&&s2.indexOf('Exception')<0;
   }catch(e2){}
   var ct2=ok2?(Date.now()-st)+'ms':'超时/验证';
   jv.put('ijDelay'+(q+1),ct2);res.push(clean[q]+'='+ct2);
  }
 }
 IJ_toast(jv,'② 测速完成（总 '+(Date.now()-t0)+'ms）：'+res.join(' , ')+'；点各线路按钮即时切换');
 IJ_reUi(jv);
 return res.join('|');
}
function IJ_switch(jv,n){
 IJ_toast(jv,'① 正在切换到线路 '+n+' …');
 var list=IJ_gv(jv,'ijLines','').split('|'),i=Number(n)-1;
 if(i<0||i>=list.length||!list[i]){IJ_toast(jv,'✗ 线路 '+n+' 不存在，请先获取路线');return '';}
 var v=list[i].replace(/\/+$/,'');
 jv.put('ijLine',v);
 IJ_toast(jv,'② 已切换：'+v+'（下一次搜索/发现/目录即时生效）');
 IJ_reUi(jv);
 return v;
}
function IJ_check(jv){
 IJ_toast(jv,'① 正在检查线路连通性与登录状态…');
 var base=IJ_line(jv),s='';
 try{s=String(jv.ajax(base+'/'))}catch(e){s='ERR '+e;}
 var waf=s.indexOf('宝塔防火墙')>=0||s.indexOf('请输入验证码')>=0;
